  const t = /^(\d{2}):(\d{2})$/.exec(timeET);
  if (!d || !t) return null;
  const guess = Date.UTC(+d[1], +d[2] - 1, +d[3], +t[1], +t[2]);
  let utc = guess - offsetAt(guess, ET);
  utc = guess - offsetAt(utc, ET); // second pass settles DST edges
  const back = parts(utc, ET);
  if (back.year !== +d[1] || back.month !== +d[2] || back.day !== +d[3] || back.hour !== +t[1] || back.minute !== +t[2]) return null;
  return new Date(utc).toISOString();
